  ["Roomscale movement"] = "Переміщення кімнатою",
  ["Move the player capsule with physical horizontal head movement.\nUses native collision/steps and preserves stick or WASD movement.\nSuspended in menus, vehicles and scripted movement."] = "Рухає капсулу гравця за фізичним горизонтальним рухом голови.\nВикористовує рідні колізії та сходинки, зберігає рух стіком або WASD.\nВимикається в меню, транспорті та скриптовому русі.",
  ["Stick / snap only"] = "Лише стік / ривки",
  ["Head + free-look cone"] = "Голова + конус вільного огляду",
  ["HMD + controllers"] = "HMD + контролери",
  ["Hybrid (default)"] = "Гібрид (типово)",
  ["Body rotation"] = "Поворот тіла",
  ["Hybrid: use the head cone while upright.\nLooking down by 10 degrees or bending by 5 degrees uses HMD + controllers.\nReturn below 8 / 3 degrees; the current body heading is preserved at handover.\nHMD + controllers always disables the body cones. Missing tracking holds heading."] = "Гібрид: стоячи працює конус голови.\nПогляд униз на 10° або нахил на 5° перемикає на HMD + контролери.\nПовернення нижче 8 / 3°; поточний напрямок тіла під час перемикання зберігається.\nHMD + контролери завжди вимикає конуси тіла. Без трекінгу напрямок утримується.",
  ["Never (VRIK always on)"] = "Ніколи (VRIK завжди увімк.)",
  ["Staged scenes and up (Tier 2+)"] = "Постановочні сцени й вище (Tier 2+)",
  ["Tier 3 and up"] = "Tier 3 і вище",
  ["Cinematics (Tier 4+)  [default]"] = "Ролики (Tier 4+)  [типово]",
