  ["active cone %.1f deg | realign %+.1f deg | head-vs-body %+.1f deg"] = "активний конус %.1f° | доворот %+.1f° | голова-тіло %+.1f°",
  ["Hand IK Calibration (per hand: R = right, L = left)"] = "Калібрування IK рук (для кожної: R = права, L = ліва)",
