  ["AUTO-CALIBRATING: stretch arms STRAIGHT OUT to the sides,"] = "АВТОКАЛІБРУВАННЯ: витягніть руки ПРЯМО В БОКИ,",
  ["stand straight facing forward. Hold for %.1fs (%.0f%%)."] = "станьте рівно обличчям уперед. Тримайте %.1f с (%.0f%%).",
  ["Start Auto-Calibration (T-pose, 4s)"] = "Почати автокалібрування (T-поза, 4 с)",
  ["Press once, then stretch BOTH gizmo hands OUT to the sides at shoulder height\nand stand straight facing forward. The mod measures the visible controller\npositions, computes shoulder pivots + arm scale, and saves the result\nto vrik_calibration.ini."] = "Натисніть один раз, потім витягніть ОБИДВІ руки-гізмо В БОКИ на рівні плечей\nі станьте рівно обличчям уперед. Мод виміряє видимі положення\nконтролерів, обчислить опори плечей і масштаб рук та збереже результат\nу vrik_calibration.ini.",
  ["Saved."] = "Збережено.",
  ["Camera: neck + 15 cm forward, eyes + 10 cm up"] = "Камера: шия + 15 см уперед, очі + 10 см угору",
  ["Reset camera to neck"] = "Скинути камеру до шиї",
  ["Uses the neutral neck, 15 cm forward and 10 cm above reference eyes.\nResets camera trims; no stance, head direction or Bake measurement is needed."] = "Нейтральна шия, 15 см уперед і 10 см вище опорних очей.\nСкидає підлаштування камери; стійка, напрямок голови й замір Bake не потрібні.",
  ["Clear trim"] = "Скинути підлаштування",
