  ["Apply Calibration"] = "Застосувати калібрування",
  ["Save"] = "Зберегти",
  ["Load"] = "Завантажити",
  ["Reset Defaults"] = "Скинути до типових",
  ["Stereo module not installed."] = "Стереомодуль не встановлено.",
  ["The engine hooks did not load, so everything below is inert and the headset is on the plain mono path. Either CyberpunkVR_StereoModuleEnable is 0, or bin\\x64\\vrport_nostereo.txt exists. See the \"Stereo:\" line in cyberpunkvrport.log."] = "Хуки рушія не завантажилися, тож усе нижче неактивне, а шолом працює у звичайному моно-режимі. Або CyberpunkVR_StereoModuleEnable дорівнює 0, або існує bin\\x64\\vrport_nostereo.txt. Див. рядок \"Stereo:\" у cyberpunkvrport.log.",
  ["LEFT"] = "ЛІВЕ",
  ["RIGHT"] = "ПРАВЕ",
  ["Stereo active  (%s = VRCAM, %s = MAIN)"] = "Стерео активне  (%s = VRCAM, %s = MAIN)",
  ["No second eye right now -> both eyes get MAIN (mono)"] = "Другого ока зараз немає -> обидва ока отримують MAIN (моно)",
  ["Expected in menus and while loading. If it stays here in gameplay: the VRCAM component is off, or vrcam.json names a camera the player entity does not carry."] = "Очікувано в меню та під час завантаження. Якщо так лишається в грі: компонент VRCAM вимкнено або vrcam.json вказує камеру, якої немає в сутності гравця.",
  ["Stereo submit off -> both eyes get MAIN (mono)"] = "Надсилання стерео вимкнено -> обидва ока отримують MAIN (моно)",
  ["vrcam eye age %u ms  (stale over %u)   eye submits %llu"] = "вік ока vrcam %u мс  (застаріле після %u)   надсилань ока %llu",
  ["vrcam eye: never produced a frame"] = "око vrcam: жодного кадру",
  ["Send VRCAM to the %s EYE"] = "Надсилати VRCAM у %s ОКО",
  ["Off = the old behaviour, MAIN duplicated into both eyes.\nOn = the %s eye gets the VRCAM view's own final colour --\nthe same image the desktop mirror shows -- re-encoded to the\nswapchain's sRGB format and scaled to the eye size."] = "Вимк. = стара поведінка, MAIN дублюється в обидва ока.\nУвімк. = %s око отримує власний фінальний колір виду VRCAM —\nте саме зображення, що в дзеркалі на моніторі, — перекодоване у\nsRGB-формат swapchain і масштабоване під розмір ока.",
  ["snapshot copies %llu   skips %llu   vrcam RTV hits %llu"] = "копій знімка %llu   пропусків %llu   влучань RTV vrcam %llu",
  ["Eye staleness limit (ms)"] = "Межа застарівання ока (мс)",
  ["How long the last VRCAM frame stays usable. Past this the %s\neye falls back to MAIN -- one eye frozen while the other moves\nis far worse to look at than mono."] = "Скільки останній кадр VRCAM лишається придатним. Після цього %s\nоко переходить на MAIN — одне застигле око при рухомому іншому\nдивитися значно гірше, ніж моно.",
  ["VRCAM DLSS: %s  (follows MAIN's upscaler, no switch)"] = "VRCAM DLSS: %s  (слідує апскейлеру MAIN, без перемикача)",
  ["ON"] = "УВІМК.",
  ["off"] = "вимк",
  ["On whenever MAIN is upscaling with DLSS: vrcam gets its own\nStreamline viewport and renders below its target.\nOff for DLAA / TAA / no upscaler. Change it in the game's\ngraphics settings, not here."] = "Увімкнено, коли MAIN апскейлить через DLSS: vrcam отримує власний\nв'юпорт Streamline і рендерить нижче цільової роздільності.\nВимкнено при DLAA / TAA / без апскейлера. Змінюється в графічних\nналаштуваннях гри, а не тут.",
  ["Match VRCAM projection to MAIN  (fov / zoom / near / far)"] = "Проєкція VRCAM як у MAIN  (fov / zoom / near / far)",
  ["VRCAM component  (RTTI Toggle: force ON/OFF)"] = "Компонент VRCAM  (RTTI Toggle: примусово УВІМК/ВИМК)",
  ["component %s   camera %s"] = "компонент %s   камера %s",
  ["view nodes: main %llu   other %llu   vrcam %llu"] = "вузли виду: main %llu   інші %llu   vrcam %llu",
  ["VRCAM Mirror  (separate window, for capture)"] = "Дзеркало VRCAM  (окреме вікно, для запису)",
  ["vrcam fov %.2f  (asset %.2f)   main yy %.5f  fov %.2f   ADS x%.3f"] = "vrcam fov %.2f  (асет %.2f)   main yy %.5f  fov %.2f   ADS x%.3f",
  ["Diagnostics"] = "Діагностика",
  ["Compact ADS camera telemetry (in-headset)"] = "Компактна телеметрія камери ADS (у шоломі)",
  ["A small panel that stays up after F10 is closed, reporting what the ENGINE did to the camera when the sights came up:\ndelta and peak in centimetres, right/forward/up in the heading's own basis, against a baseline captured while hip firing.\nStereo submission is unaffected."] = "Маленька панель, що лишається після закриття F10 і показує, що РУШІЙ зробив із камерою під час підйому приціла:\nзсув і пік у сантиметрах, праворуч/уперед/угору в базисі напрямку, відносно бази, знятої під час стрільби від стегна.\nНа надсилання стерео не впливає.",
  ["Telemetry X"] = "Телеметрія X",
  ["Telemetry Y"] = "Телеметрія Y",
  ["Normalised position in the eye image"] = "Нормалізована позиція в зображенні ока",
  ["Stereo logging -> cyberpunkvrport.log"] = "Лог стерео -> cyberpunkvrport.log",
  ["Committed snapshot of the VRCAM final"] = "Зафіксований знімок фіналу VRCAM",
  ["Off = read the engine's transient directly. That target is a\nframe-graph allocation which a later pass aliases, which is what\nmade the image alternate bright/dark. Leave on."] = "Вимк. = читати тимчасову ціль рушія напряму. Ця ціль —\nвиділення frame graph, яке пізніше перевикористовує інший прохід, через\nщо картинка блимала світлим/темним. Залиште ввімкненим.",
  ["Snapshot at the tonemap node instead of RenderFinal2D"] = "Знімок на вузлі тонмапінгу замість RenderFinal2D",
  ["Node CPU profiler  (per-node self+incl ms)"] = "CPU-профайлер вузлів  (власн.+вкл. мс на вузол)",
  ["frame %.2f ms   dispatch: main %.2f (%u)  vrcam %.2f (%u)"] = "кадр %.2f мс   диспетчер: main %.2f (%u)  vrcam %.2f (%u)",
  ["Dump node audit -> log  (resets window)"] = "Аудит вузлів -> лог  (скидає вікно)",
  ["top %d by self ms/frame   (main | vrcam)"] = "топ %d за власн. мс/кадр   (main | vrcam)",
  ["Driving -- hands on the wheel"] = "Водіння — руки на кермі",
  ["Grab the wheel with the grips"] = "Хапати кермо грипами",
  ["While DRIVING, bring a hand to where the driving animation holds the\nwheel (or the handlebars) and squeeze that grip: the arm is handed back\nto the game's own animation -- hand on the wheel, fingers wrapped around\nit -- instead of following the controller. Release the grip and it goes\nback to your hand.\n\nEach hand is independent: hold the wheel with one and keep the other on\na gun. While a hand is at the wheel that grip does nothing else (no\nholster equip, no magazine grab)."] = "Під час ВОДІННЯ піднесіть руку туди, де анімація тримає\nкермо (або кермо мотоцикла), і стисніть грип: рука переходить\nдо рідної анімації гри — долоня на кермі, пальці обхоплюють\nйого — замість слідувати за контролером. Відпустіть грип, і вона\nповернеться до вашої руки.\n\nРуки незалежні: тримайте кермо однією, а в іншій — зброю.\nПоки рука на кермі, цей грип більше нічого не робить (не\nдістає з кобури, не хапає магазин).",
  ["Grab radius (m)"] = "Радіус захоплення (м)",
  ["How close your hand has to be to the animated hand before the\ngrip counts as grabbing the wheel. Bigger = easier to catch a\nwheel you cannot see; too big and every grip in a car grabs."] = "Наскільки близько рука має бути до анімованої руки, щоб\nгрип вважався захопленням керма. Більше = легше впіймати кермо,\nякого не видно; забагато — і будь-який грип в авто хапає кермо.",
  ["Car full lock at (deg)"] = "Повний поворот керма при (°)",
  ["Wheel sensitivity: hand rotation from the grab position to full lock.\nOne hand uses a hub calibrated where you grab; two use their connecting line.\nAdding or releasing a hand keeps the current turn.\n180 = a half turn to either full lock (default). Lower = more sensitive.\nThe car's cabin wheel has twice its native travel; road-wheel lock is unchanged.\nTravel beyond full lock keeps the same neutral position."] = "Чутливість керма: поворот руки від точки захоплення до упору.\nОдна рука використовує маточину, відкалібровану в місці захоплення; дві — лінію між ними.\nДодавання або відпускання руки зберігає поточний поворот.\n180 = пів оберту до упору в кожен бік (типово). Менше = чутливіше.\nКермо в салоні має вдвічі більший хід, ніж рідне; кут коліс не змінюється.\nХід за упором зберігає те саме нейтральне положення.",
  ["Steering deadzone (deg)"] = "Мертва зона керма (°)",
  ["Tilt around centre that steers nothing at all.\nRaise it if the car drifts while you hold the wheel straight;\nevery degree here is a degree of dead wheel off centre.\nThe full range still ends at 'Full lock at', so widening the\ndeadzone does not make the steering jump."] = "Нахил навколо центру, який зовсім не кермує.\nЗбільште, якщо авто зносить, поки ви тримаєте кермо прямо;\nкожен градус тут — градус мертвого керма від центру.\nПовний діапазон усе одно закінчується на «Повний поворот керма при», тому\nрозширення мертвої зони не дає ривка кермування.",
  ["Steering prediction"] = "Передбачення кермування",
  ["Gently anticipate a continuing turn from recent hand movement.\nLimited to 8 ms and 0.5 degrees; neutral stays unchanged.\nPrediction stops on a pause, reversal or grip change.\nOff by default. It cannot anticipate the start of a turn."] = "М'яко передбачає продовження повороту за недавнім рухом руки.\nНе більше 8 мс і 0.5°; нейтраль не змінюється.\nПередбачення зупиняється при паузі, зміні напрямку або хвату.\nВимк. типово. Початок повороту передбачити не можна.",
  ["Prediction horizon (ms)"] = "Горизонт передбачення (мс)",
  ["Horn -- hand on the wheel hub"] = "Клаксон — рука на центрі керма",
  ["While DRIVING, put a hand on the MIDDLE of the wheel -- where you would\nslap a real horn -- and the car honks for as long as it stays there.\nNo grip needed; a hand that is GRABBING the wheel never honks."] = "Під час ВОДІННЯ покладіть руку на СЕРЕДИНУ керма — туди, де\nб'ють по справжньому клаксону, — і авто сигналить, поки рука там.\nГрип не потрібен; рука, що ТРИМАЄ кермо, ніколи не сигналить.",
  ["Horn hub radius (m)"] = "Радіус центру керма (м)",
  ["How near the wheel centre the hand counts as on the hub.\nBigger = easier to find the horn without seeing it; too big\nand it reaches the rim, so every grab honks."] = "Наскільки близько до центру керма рука вважається на маточині.\nБільше = легше знайти клаксон наосліп; забагато —\nі зона дійде до обода, і кожне захоплення сигналитиме.",
  ["Trigger fires the gun while driving"] = "Гачок стріляє під час водіння",
  ["Draw a weapon in the driver seat and the RIGHT TRIGGER stops being the\nthrottle and becomes the gun: drive with the left hand on the wheel and\nshoot with the right.\n\nThe throttle LATCHES at whatever it was when the weapon came out, so the\ncar keeps rolling, and the LEFT STICK forward/back trims that speed while\nyou shoot. Holster the weapon and the trigger is the throttle again.\n\nWhile the weapon is out the left stick's forward/back is taken by the\ntrim: no lean / rock and no autodrive gesture until you holster."] = "Дістаньте зброю на місці водія, і ПРАВИЙ ГАЧОК перестає бути\nгазом і стає пострілом: кермуйте лівою рукою і\nстріляйте правою.\n\nГаз ФІКСУЄТЬСЯ на тому рівні, яким був, коли ви дістали зброю, тож\nавто продовжує їхати, а ЛІВИЙ СТІК уперед/назад підлаштовує швидкість, поки\nви стріляєте. Сховайте зброю, і гачок знову стане газом.\n\nПоки зброя в руках, уперед/назад лівого стіка зайняті\nпідлаштуванням: ніяких нахилів / розгойдування й жесту автоводіння, доки не сховаєте зброю.",
  ["Throttle trim rate (/s)"] = "Швидкість підлаштування газу (/с)",
  ["How much of the throttle's full travel the left stick adds or\nremoves per second while a weapon is out.\n0.5 = two seconds held to go from idle to floored."] = "Яку частку повного ходу газу лівий стік додає або\nприбирає за секунду, поки зброя в руках.\n0.5 = дві секунди утримання від холостого до повного газу.",
  ["driving %d   at wheel  L %d R %d   hold  L %.2f R %.2f"] = "водіння %d   на кермі  L %d R %d   хват  L %.2f R %.2f",
  ["steer  %+.1f deg  ->  stick %+.2f     horn  L %d R %d"] = "кермо  %+.1f°  ->  стік %+.2f     клаксон  L %d R %d",
  ["SEATED CAMERA OFFSET"] = "ЗСУВ КАМЕРИ СИДЯЧИ",
  ["Head offsets in GENERAL are a standing calibration. Seated, the game's own\nvehicle camera is already where it should be -- which is why the port drops\nits two automatic bakes in a vehicle -- so a standing offset carries the view\noff the seat instead of correcting it.\n\nThese three are added to the Head sliders while you are in a vehicle and\nignored the moment you step out, so the car and the street can be tuned\nseparately. Zero = the car keeps exactly the offset it has today."] = "Зсуви голови на вкладці ЗАГАЛЬНІ — калібрування стоячи. Сидячи рідна камера\nтранспорту вже там, де треба, — тому порт вимикає\nсвої два автопідлаштування в транспорті, — і зсув для стоячи виводить вид\nіз сидіння, замість того щоб виправляти його.\n\nЦі три значення додаються до повзунків голови, поки ви в транспорті, і\nігноруються, щойно ви виходите, тож авто й вулицю можна налаштувати\nокремо. Нуль = авто зберігає рівно той зсув, що є зараз.",
  ["Car Head X right"] = "Голова в авто X праворуч",
  ["Car Head Y forward"] = "Голова в авто Y уперед",
